/**
 * The pages of the API reference: one per contract route (openapi/cell.json and
 * control.json). The test fails if a contract route has no page here, or the other
 * way around. Title and opening sentence in Portuguese and English; the rest of the page
 * comes from the OpenAPI and the tables in tooling/openapi (descriptions, examples, access).
 */
import type { ApiPage, Group, Method, SpecId } from './types'

type Row = [slug: string, method: Method, path: string, ptTitle: string, ptDesc: string, enTitle: string, enDesc: string]

const page = (spec: SpecId, [slug, method, path, ptT, ptD, enT, enD]: Row): ApiPage => ({
  kind: 'api',
  slug,
  spec,
  method,
  path,
  title: { pt: ptT, en: enT },
  description: { pt: ptD, en: enD },
})

const group = (spec: SpecId, pt: string, en: string, rows: Row[]): Group => ({ label: { pt, en }, pages: rows.map((r) => page(spec, r)) })

